cd ~/Development/[REDACTED:private]/spec && python3 - <<'EOF'
import json
f='sessions/spec/2026-10-23-spec-0fb48e95-45c5-4b91-bfbb-b527c2511e3e.jsonl'
want=['mkdir -p $S/re','newhavendisplay','ls ..','gitee.com']
ids={}
for l in open(f):
    e=json.loads(l); m=e.get('message') or {}
    if not isinstance(m,dict): continue
    for c in m.get('content',[]) if isinstance(m.get('content'),list) else []:
        if c.get('type')=='tool_use' and c['name']=='Bash' and any(w in c['input']['command'] for w in want):
            ids[c['id']]=c['input']['command']; print('CMD:',c['input']['command'][:1200]); print()
        if c.get('type')=='tool_result' and c.get('tool_use_id') in ids:
            r=c['content']; r=r if isinstance(r,str) else json.dumps(r)
            print('OUT:',r[:700]); print('======')
EOF
grep -n "Claude Code\|claude:" sessions/spec/2026-10-23-spec-0fb48e95*.jsonl | head -2 | cut -c1-300

